def total_minutes(minutes):
    if any(value < 0 for value in minutes):
        raise ValueError('Minutes cannot be negative')
    return sum(minutes)

assert total_minutes([20, 35]) == 55
assert total_minutes([]) == 0
try:
    total_minutes([20, -2])
except ValueError:
    pass
else:
    raise AssertionError('negative minutes must be rejected')
